import json
import re
import datetime
try:
    defaults = dict(diagnostic='', phase='start', speech='', short_question='', question_failures=0, silences=0, calming_replies=0, read_cards=[], changed_years={}, change_attempts=[], pdf_attempts=0, pdf_successes=0, pending_followup='neutral', wanted_detail='all', detail_request='', wanted_currency='neutral', wanted_period='latest', digits_buffer='', selection_width=4, selection_candidates=[], selection_step='name', selection_initial='no', reading_prefix='', notice_prefix='', no_statement_branch='no', contact_ready='no', balance_ready='no', cards_ready='no', write_gate='no', handoff_destination='', bank_event='', bank_pending='', arrival_input={}, replay_input={}, deferred_input={}, after_contact='', early_week=0)
    for key, value in defaults.items():
        if key not in vars:
            vars[key] = value
    vars['route'] = ''
    vars['phase_before_error'] = str(vars['phase'])
    vars['operation_before_error'] = str(vars.get('bank_event') or vars.get('bank_pending') or 'evaluate')
    labels = ['Türk Lirası', 'Dolar', 'Euro', 'İngiliz Sterlini']
    codes = ['TL', 'USD', 'EUR', 'GBP']
    months = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
    months = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
    ones = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
    tens = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
    ordinals = ['', 'birinci', 'ikinci', 'üçüncü', 'dördüncü']
    def decode(value, js=json):
        return js.loads(value) if isinstance(value, str) else value
    for key in ['cards_private', 'selected_card', 'balance', 'contact', 'week_info', 'preview', 'changed_years', 'read_cards', 'change_attempts', 'selection_candidates']:
        if isinstance(vars.get(key), str):
            vars[key] = decode(vars[key])
    def norm(value, rx=re):
        return rx.sub(r'\s+', ' ', str(value).replace('İ', 'i').replace('I', 'ı').lower()).strip()
    def alias(value, normalize=norm, rx=re):
        text = normalize(value)
        text = rx.sub(r"[’'](?:ım|im|um|üm|ı|i|u|ü|ın|in|un|ün)$", '', text)
        text = rx.sub(r'\b(?:benim|olanı|olanın|olan|kredi|kartımın|kartım|kartının|kartınızın|kartını|kartı|kart|ekstre|ekstresi|ekstrem|ekstremin|borcunu|borcum|borcumu|borcu)\b', ' ', text)
        return normalize(text).strip(' .?!,;:')
    def total_only(text, normalize=norm, rx=re):
        value = normalize(text)
        restricted = bool(rx.search(r'\b(?:sadece|yalnız|yalnızca)\b', value))
        total = bool(rx.search(r'\btoplam(?:ı|ını|ım|ımı)?\b|gelecek dönemler dahil|cari bor', value))
        return restricted and total
    def number(value, one=ones, ten=tens):
        n = int(value)
        if n == 0:
            return one[0]
        parts = []
        for scale, name in [(1000000000000, 'trilyon'), (1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin'), (1, '')]:
            group, n = divmod(n, scale)
            if not group:
                continue
            if group >= 1000:
                raise ValueError('amount_range')
            words = []
            if group // 100:
                if group // 100 > 1:
                    words.append(one[group // 100])
                words.append('yüz')
            rest = group % 100
            if rest // 10:
                words.append(ten[rest // 10])
            if rest % 10:
                words.append(one[rest % 10])
            if scale == 1000 and group == 1:
                words = []
            if name:
                words.append(name)
            parts.extend(words)
        return ' '.join(parts)
    def minor(value, rx=re):
        if isinstance(value, bool):
            raise ValueError('invalid_amount')
        text = str(value).strip().lower()
        if not rx.fullmatch(r'-?\d+(?:\.\d+)?(?:e[+-]?\d+)?', text):
            raise ValueError('invalid_amount')
        negative = text.startswith('-')
        text = text.lstrip('-')
        exponent = 0
        if 'e' in text:
            text, exp = text.split('e')
            exponent = int(exp)
        bits = text.split('.')
        digits = bits[0] + (bits[1] if len(bits) > 1 else '')
        position = len(bits[0]) + exponent
        if position < 0:
            digits = '0' * (-position) + digits
            position = 0
        if position > len(digits):
            digits += '0' * (position - len(digits))
        fraction = digits[position:]
        if len(fraction) > 2 and any(c != '0' for c in fraction[2:]):
            raise ValueError('unsupported_precision_no_rounding')
        amount = int(digits[:position] or '0') * 100 + int((fraction + '00')[:2])
        return -amount if negative else amount
    def money(value, currency, cv=minor, nw=number, names=labels, currencies=codes):
        amount = cv(value)
        if amount < 0:
            raise ValueError('negative_debt_speech')
        whole, fraction = divmod(amount, 100)
        unit = 'kuruş' if currency == 'TL' else ('peni' if currency == 'GBP' else 'sent')
        return nw(whole) + ' ' + names[currencies.index(currency)] + ((' ' + nw(fraction) + ' ' + unit) if fraction else '')
    def date_value(text, dt=datetime):
        return dt.datetime.strptime(str(text), '%d.%m.%Y').date()
    def date_speech(text, parse=date_value, names=months):
        value = parse(text)
        return str(value.day) + ' ' + names[value.month - 1] + ' ' + str(value.year)
    def safe_name(value, rx=re):
        text = str(value or '').strip()
        return '' if rx.search(r'talimat|yok say|ignore|system|prompt|numarasını oku|\d[\d *-]{5,}\d', text, rx.I) else text
    def intro(card, sn=safe_name, digits=ones):
        last = str(card.get('cardNumberLast4', ''))
        if len(last) != 4 or not last.isdigit():
            raise ValueError('missing_last_four')
        name = sn(card.get('productName', ''))
        return 'Sonu ' + ' '.join(digits[int(c)] for c in last) + ' ile biten ' + (name + ' ' if name else '')
    def joined(items):
        if not items:
            return ''
        return items[0] if len(items) == 1 else ', '.join(items[:-1]) + ' ve ' + items[-1]
    def eligible(card):
        return isinstance(card, dict) and card.get('status') == 'A' and str(card.get('isMainCard')).lower() == 'true'
    def authorized(v=vars, el=eligible):
        card = v.get('selected_card', {})
        return v.get('cards_ready') == 'yes' and v.get('cards_customer') == str(v.get('customerNumber', '')) and card in v.get('cards_private', []) and el(card) and v.get('balance_ready') == 'yes' and v.get('balance_card') == card.get('cardNumber')
    def question(phase, text, short='', key='', v=vars):
        identity = key or phase
        old = v.get('question_key', v.get('phase', ''))
        if old != identity:
            v['question_failures'] = 0
        prefix = (str(v.get('notice_prefix', '')) + ' ' + str(v.get('reading_prefix', ''))).strip()
        v['notice_prefix'] = ''
        v['reading_prefix'] = ''
        v['phase'] = phase
        v['question_key'] = identity
        v['speech'] = ((prefix + ' ') if prefix else '') + text.strip()
        v['short_question'] = short or text.strip()
        v['route'] = phase
    def close(text, destination='main_menu', include_reading=False, v=vars):
        prefix = str(v.get('notice_prefix', '')).strip()
        if include_reading and v.get('reading_prefix'):
            prefix = (prefix + ' ' + str(v['reading_prefix'])).strip()
        v['notice_prefix'] = ''
        v['reading_prefix'] = ''
        v['phase'] = 'finished'
        v['speech'] = ((prefix + ' ') if prefix else '') + text.strip()
        v['short_question'] = ''
        v['handoff_destination'] = destination
        v['write_gate'] = 'no'
        v['replay_input'] = {}
        v['deferred_input'] = {}
        v['arrival_input'] = {}
        v['after_contact'] = ''
        v['route'] = 'finish'
    def failure(v=vars, q=question, end=close):
        v['question_failures'] = int(v.get('question_failures', 0)) + 1
        if v['question_failures'] >= 3:
            end('Size şu anda yardımcı olamıyorum. Sizi ana menüye aktarıyorum.')
        else:
            q(v['phase'], v['short_question'], v['short_question'], v.get('question_key', v['phase']))
    def card_prompt(cards, sn=safe_name, ins=intro):
        choices = []
        for card in cards:
            name = sn(card.get('productName', '')) or ins(card).strip() + ' kart'
            if name not in choices:
                choices.append(name)
        return 'Hangi kartınızın borcunu öğrenmek istersiniz?' + (' Örneğin, ' + ' veya '.join(choices[:2]) + ' diyebilirsiniz.' if choices else '')
    def pick(card, v=vars):
        if v.get('cards_customer') != str(v.get('customerNumber', '')) or card not in v.get('cards_private', []):
            raise ValueError('selection_prerequisite')
        v['selected_card'] = dict(card)
        v['balance_ready'] = 'no'
        v['week_ready'] = 'no'
        v['preview_ready'] = 'no'
        v['write_gate'] = 'no'
        v['write_plan'] = {}
        v['email_challenge'] = {}
        v['week_challenge'] = {}
        v['digits_buffer'] = ''
        v['selection_candidates'] = []
        v['selection_width'] = 4
        v['selection_step'] = 'name'
        v['reading_prefix'] = ''
        v['email_question'] = ''
        v['phase'] = 'balance_wait'
