            vars['pending_followup'] = 'neutral'
            vars['early_week'] = 0
            vars['route'] = 'evaluate'
    if not vars['route']:
        raise ValueError('uninitialized_route')
except Exception as exc:
    vars['diagnostic'] = str(type(exc)) + ': evaluate_policy_or_prerequisite'
    week_error = str(vars.get('operation_before_error', '')).startswith('statement_week_') or str(vars.get('phase_before_error', '')).startswith(('week', 'preview', 'change'))
    vars['bank_event'] = ''
    vars['bank_pending'] = ''
    vars['bank_payload'] = {}
    vars['arrival_input'] = {}
    vars['replay_input'] = {}
    vars['deferred_input'] = {}
    vars['after_contact'] = ''
    vars['write_gate'] = 'no'
    vars['route'] = 'finish'
    vars['phase'] = 'finished'
    vars['handoff_destination'] = 'agent'
    vars['speech'] = 'Şu anda hesap kesim tarihinizi değiştiremiyorum, sizi müşteri temsilcimize aktarıyorum.' if week_error else 'Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum.'
